CREATE OR REPLACE FUNCTION public.encrypt_kyc_value(value text, user_id uuid)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF value IS NULL THEN
    RETURN NULL;
  END IF;
  
  RETURN pgp_sym_encrypt(
    value, 
    encode(digest(user_id::text || 'chatr_kyc_key_v1', 'sha256'), 'hex')
  );
END;
$function$;

